// What a business photo is, in storage and in a page (ADR 0011;
// docs/specs/business-registration.md, "Photos are stored as two WebP sizes in
// R2 under opaque keys (v2)"; docs/specs/public-directory.md, "Only the photo
// generated by the server is rendered", "Photo weight does not break the 4G
// budget" and "The photo of an unpublished business is referenced on no public
// surface (v2)"). Pure: it never reads the environment.
//
// A business stores one photo key (`photoKey`), opaque and generated by the
// server: 24 characters of the business identifier's alphabet, about 119 bits,
// so nobody can guess one, and never an identifier, which has 10. The photo is
// two WebP objects in the environment's public media bucket, under the
// `photos/` prefix and that key:
//
//   photos/<photoKey>/card.webp   the variant of the listing card, 400×400
//   photos/<photoKey>/full.webp   the variant of the business's card, 1200×900
//
// Whoever writes them (the registration, the fictitious seed) writes those
// sizes, as WebP, with PHOTO_CACHE_CONTROL; whoever deletes a photo deletes
// both objects. A page renders a photo only through photoUrl, which builds the
// address from the environment's media base and a stored key that has exactly
// the shape newPhotoKey gives: anything else stored (a URL, `data:`,
// `javascript:`, a path, any other string) is no photo at all.
import { customAlphabet } from "nanoid";
import { BUSINESS_ID_ALPHABET } from "../business/id.ts";

export const PHOTO_KEY_LENGTH = 24;
export const PHOTO_KEY_PATTERN = `^[${BUSINESS_ID_ALPHABET}]{${PHOTO_KEY_LENGTH}}$`;

/** A new photo key; the unique index on `photo_key` still rejects a repeat. */
export const newPhotoKey: () => string = customAlphabet(BUSINESS_ID_ALPHABET, PHOTO_KEY_LENGTH);

const photoKeyRegExp = new RegExp(PHOTO_KEY_PATTERN);

/** Whether a stored value is a photo key the server generated. */
export function isPhotoKey(value: string | null | undefined): value is string {
  return typeof value === "string" && photoKeyRegExp.test(value);
}

/** The prefix of the business photos in the media bucket. */
export const PHOTOS_PREFIX = "photos/";

/** The two sizes of a photo (ADR 0011). */
export type PhotoVariant = "card" | "full";

export interface PhotoVariantSpec {
  /** The object's name under the photo key. */
  file: string;
  width: number;
  height: number;
  /** The most the object may weigh (public-directory, "Photo weight does not break the 4G budget"). */
  maxBytes: number;
}

/**
 * The listing card shows `card`, a square that fills its square slot; the
 * card of the business shows `full`, 4:3, the shape of most phone photos.
 * Both fit the caps of the 4G budget: 400px and 60 KB, 1200px and 250 KB on
 * the longer side.
 */
export const PHOTO_VARIANTS: Readonly<Record<PhotoVariant, PhotoVariantSpec>> = {
  card: { file: "card.webp", width: 400, height: 400, maxBytes: 60 * 1024 },
  full: { file: "full.webp", width: 1200, height: 900, maxBytes: 250 * 1024 },
};

export const PHOTO_VARIANT_NAMES = Object.keys(PHOTO_VARIANTS) as readonly PhotoVariant[];

/** The media type of every stored variant. */
export const PHOTO_CONTENT_TYPE = "image/webp";

/**
 * The caching of every stored variant, which R2 sends with it and Cloudflare's
 * cache follows on the media hostname: a key never changes its bytes (a new
 * photo gets a new key), so browsers and the CDN keep it for a year.
 */
export const PHOTO_CACHE_CONTROL = "public, max-age=31536000, immutable";

/** The object key of one variant of a photo, such as `photos/<photoKey>/card.webp`. */
export function photoObjectKey(photoKey: string, variant: PhotoVariant): string {
  if (!isPhotoKey(photoKey)) throw new Error("photoObjectKey: not a photo key");
  return `${PHOTOS_PREFIX}${photoKey}/${PHOTO_VARIANTS[variant].file}`;
}

/** The object keys of both variants of a photo. */
export function photoObjectKeys(photoKey: string): string[] {
  return PHOTO_VARIANT_NAMES.map((variant) => photoObjectKey(photoKey, variant));
}

/** A photo as an `<img>` renders it. */
export interface PhotoSource {
  src: string;
  width: number;
  height: number;
}

/**
 * The address of one variant of a stored photo, from `base` (the media
 * hostname of the environment, such as `https://media-enmirumbo.urekz.com`,
 * or the local path the local Worker serves the local bucket at, without a
 * trailing slash), or null: when there is no base, or the stored value is
 * not a photo key the server generated.
 */
export function photoUrl(
  base: string | null,
  photoKey: string | null | undefined,
  variant: PhotoVariant,
): PhotoSource | null {
  if (base === null || !isPhotoKey(photoKey)) return null;
  const { width, height } = PHOTO_VARIANTS[variant];
  return { src: `${base}/${photoObjectKey(photoKey, variant)}`, width, height };
}
